import{_ as r,o as t,c as s,b as e,d as a,e as n,a as d,r as o}from"./app.55362c7b.js";var l="/aktivitaeten/S5-POTA-2026-10/si-0453-gradisko-jezero.jpg",u="/aktivitaeten/S5-POTA-2026-10/si-0861-shack-am-see.jpg",h="/aktivitaeten/S5-POTA-2026-10/si-0861-karte.jpg",c="/aktivitaeten/S5-POTA-2026-10/i-love-pota.jpg",p="/aktivitaeten/S5-POTA-2026-10/si-0530-shack-burgruine.jpg",g="/aktivitaeten/S5-POTA-2026-10/si-0530-aussichtspunkt.jpg",m="/aktivitaeten/S5-POTA-2026-10/si-0453-vertikal.jpg",k="/aktivitaeten/S5-POTA-2026-10/si-0453-karte.jpg",f="/aktivitaeten/S5-POTA-2026-10/si-0514-hopfengarten.jpg",S="/aktivitaeten/S5-POTA-2026-10/si-0514-betrieb.jpg",_="/aktivitaeten/S5-POTA-2026-10/qsl-karte-s5-da6max.jpg";const b={},v=e("h1",{id:"funf-parks-in-einer-woche-pota-in-slowenien",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#funf-parks-in-einer-woche-pota-in-slowenien","aria-hidden":"true"},"#"),n(" F\xFCnf Parks in einer Woche: POTA in Slowenien")],-1),z=e("p",null,[e("img",{src:l,alt:"Gradi\u0161ko jezero bei Lukovica, SI-0453"})],-1),w=e("p",null,"Vom 4. bis 9. Oktober 2026 war ich mit Funkger\xE4t und Vertikal in Slowenien unterwegs. Dank CEPT-Lizenz geht das ganz unkompliziert: einfach als S5/DA6MAX loslegen. Am Ende standen f\xFCnf aktivierte Parks im Log, darunter zwei Erstaktivierungen, 117 Aktivierungs-QSOs und mit den Kontakten aus dem Urlaubs QTH insgesamt 126 Verbindungen in 19 DXCC-Gebiete.",-1),A=e("thead",null,[e("tr",null,[e("th",null,"Datum"),e("th",null,"Park"),e("th",null,"QSOs"),e("th",null,"Band/Mode")])],-1),D=e("td",null,"04.10.",-1),P={href:"https://pota.app/#/park/SI-0004",target:"_blank",rel:"noopener noreferrer"},O=n("SI-0004 Gozdni rezervat Greben Rogle"),T=e("td",null,"10",-1),B=e("td",null,"15m SSB + FT8",-1),j=e("td",null,"05.10.",-1),I={href:"https://pota.app/#/park/SI-0861",target:"_blank",rel:"noopener noreferrer"},L=n("SI-0861 Krajinski park Mariborsko jezero"),M=e("td",null,"21",-1),E=e("td",null,"40m SSB, Erstaktivierung",-1),H=e("td",null,"06.10.",-1),F={href:"https://pota.app/#/park/SI-0530",target:"_blank",rel:"noopener noreferrer"},Q=n("SI-0530 Stari grad Dravograd"),V=e("td",null,"21 + 2 P2P",-1),x=e("td",null,"40m SSB, Erstaktivierung",-1),W=e("td",null,"07.10.",-1),G={href:"https://pota.app/#/park/SI-0453",target:"_blank",rel:"noopener noreferrer"},R=n("SI-0453 Gradi\u0161ko jezero - Lukovica"),C=e("td",null,"36",-1),X=e("td",null,"40m SSB",-1),K=e("td",null,"09.10.",-1),N={href:"https://pota.app/#/park/SI-0514",target:"_blank",rel:"noopener noreferrer"},U=n("SI-0514 U\u010Dna vodna pot Dobrava - Radlje ob Dravi"),Z=e("td",null,"29 + 1 P2P",-1),J=e("td",null,"40m SSB",-1),Y=d('<p><strong>Ausr\xFCstung:</strong> Yaesu FT-891 (im Urlaubs QTH das FT-710), 100 W in SSB, eine 1/4-Lambda-Vertikal mit Verl\xE4ngerungsspule f\xFCr 40m und 32 Radials.</p><h2 id="warum-slowenien-ein-tolles-pota-land-ist" tabindex="-1"><a class="header-anchor" href="#warum-slowenien-ein-tolles-pota-land-ist" aria-hidden="true">#</a> Warum Slowenien ein tolles POTA-Land ist</h2><p>Slowenien ist klein, gr\xFCn und hat erstaunlich viele POTA-Referenzen: Landschaftsparks, Waldreservate, Seen, Burgruinen und Lehrpfade. Manche davon wurden noch nie aktiviert, zwei davon durfte ich in dieser Woche zum ersten Mal in die Luft bringen. Die Wege zwischen den Parks sind kurz, an vielen Seen stehen Picknicktische, und die Menschen sind sehr freundlich.</p><p>Funktechnisch sitzt man in S5 mitten in Europa. Auf 40m kamen die Anrufe aus Deutschland, Polen, Italien, Frankreich, den Niederlanden und der Schweiz, oft mit richtigem Pile-up. F\xFCr die J\xE4ger ist S5 ein begehrtes Land, und das merkt man.</p><h2 id="die-parks-finden-nicht-immer-einfach" tabindex="-1"><a class="header-anchor" href="#die-parks-finden-nicht-immer-einfach" aria-hidden="true">#</a> Die Parks finden: nicht immer einfach</h2><p>Die gr\xF6\xDFte H\xFCrde war nicht das Funken, sondern die Frage: Wo genau ist eigentlich der Park? Das Kartenmaterial ist in Slowenien teils unvollst\xE4ndig. Parkgrenzen fehlen in vielen Karten-Apps, und manche Referenz ist eher ein Gebiet als ein klar markierter Ort.</p><p>Was geholfen hat:</p><ul><li><strong>Die Parkseite in pota.app:</strong> Dort stehen Koordinaten, Lage und oft Links zu offiziellen slowenischen Quellen. Damit l\xE4sst sich die Lage meistens gut eingrenzen.</li><li><strong>Ein \xDCbersetzer:</strong> Die offiziellen Seiten sind auf Slowenisch. Mit einem \xDCbersetzer im Browser oder auf dem Handy versteht man schnell, was gemeint ist.</li><li><strong>Ein paar Vokabeln:</strong> <em>krajinski park</em> ist ein Landschaftspark, <em>gozdni rezervat</em> ein Waldreservat, <em>jezero</em> ein See, <em>stari grad</em> eine alte Burg und <em>u\u010Dna pot</em> ein Lehrpfad. Damit erkennt man schon am Namen, wonach man vor Ort suchen muss.</li><li><strong>Vor Ort umschauen:</strong> Wenn die Grenze unklar ist, lieber ein paar hundert Meter weiter ins Gebiet hinein gehen. Seeufer, Burgberge und Lehrpfade sind meist eindeutig.</li></ul><h2 id="_04-10-si-0004-greben-rogle-plan-b-auf-15m" tabindex="-1"><a class="header-anchor" href="#_04-10-si-0004-greben-rogle-plan-b-auf-15m" aria-hidden="true">#</a> 04.10.: SI-0004 Greben Rogle - Plan B auf 15m</h2><p>Der Start war holprig: Die Spule f\xFCr 40m wollte nicht. Also blieb nur 15m ohne Spule, mit einer Mischung aus SSB und FT8. Es reichte genau f\xFCr 10 QSOs und damit f\xFCr die Aktivierung. Und die hatten es in sich: In SSB kamen die Azoren (CU3HN, rund 3.550 km) und Lissabon ins Log, in FT8 sogar Japan (JA2HYD) und Indonesien (YB1HR, rund 10.650 km). Manchmal ist Plan B gar nicht so schlecht.</p><h2 id="_05-10-si-0861-mariborsko-jezero-erstaktivierung" tabindex="-1"><a class="header-anchor" href="#_05-10-si-0861-mariborsko-jezero-erstaktivierung" aria-hidden="true">#</a> 05.10.: SI-0861 Mariborsko jezero - Erstaktivierung</h2><p><img src="'+u+'" alt="Der Shack am Ufer der Drava"></p><p>Am n\xE4chsten Tag lief es mit einer 40m-Spule, und es ging an den Fluss Drava ausserhalb bei Maribor. Ein alter Holztisch direkt am Wasser wurde zum Shack. SI-0861 war bis dahin noch nie aktiviert worden, ich durfte also der Erste sein. Kaum gespottet, ging es auf 40m SSB los: 21 QSOs in gut 21 Minuten, aus 9 DXCC-Gebieten.</p><p><img src="'+h+'" alt="QSO-Karte von SI-0861: ein Stern mit Slowenien in der Mitte"></p><p>Nach dem Abbau stand auf der staubigen Heckscheibe nur noch eins:</p><p><img src="'+c+'" alt="I love POTA auf der Heckscheibe"></p><h2 id="_06-10-si-0530-stari-grad-dravograd-erstaktivierung-an-der-burgruine" tabindex="-1"><a class="header-anchor" href="#_06-10-si-0530-stari-grad-dravograd-erstaktivierung-an-der-burgruine" aria-hidden="true">#</a> 06.10.: SI-0530 Stari grad Dravograd - Erstaktivierung an der Burgruine</h2><p><img src="'+p+'" alt="Shack auf der Steinbank vor der Burgruine Dravograd"></p><p>Strahlend blauer Himmel und eine alte Turmruine, auf der oben die B\xE4ume wachsen: Zwei Holzb\xE4nke mit Steinsockel wurden zum perfekten Shack. Und auch diese Referenz war noch nie aktiviert worden, die zweite Erstaktivierung in zwei Tagen. 21 QSOs in 30 Minuten aus 7 DXCC-Gebieten, dazu 2 Park-to-Park-Verbindungen. Mit EA2EZ in Zaragoza gelang das weiteste 40m-SSB-QSO der Woche, rund 1.380 km. Ich hatte allerdings den Eindruck, dass ich besser geh\xF6rt wurde, als ich selbst aufnehmen konnte. Manches Rufzeichen musste ich mehrmals abfragen.</p><p>Besonders gefreut haben mich die 3 Draussenfunker-zu-Draussenfunker-QSOs. Danke euch!</p><p><img src="'+g+'" alt="Aussichtspunkt \xFCber Dravograd"></p><h2 id="_07-10-si-0453-gradisko-jezero-der-langste-pile-up" tabindex="-1"><a class="header-anchor" href="#_07-10-si-0453-gradisko-jezero-der-langste-pile-up" aria-hidden="true">#</a> 07.10.: SI-0453 Gradi\u0161ko jezero - der l\xE4ngste Pile-up</h2><p><img src="'+m+'" alt="Die Vertikal mit Radials auf der Kleewiese"></p><p>Am Gradi\u0161ko jezero bei Lukovica stand die Vertikal mit ihren gelben Radials mitten auf der Kleewiese, der Campingstuhl direkt davor mit Blick aufs Wasser. Fast eine Stunde lief der Betrieb: 36 QSOs in 58 Minuten aus 8 DXCC-Gebieten. Es kamen tolle Rapporte aus der Heimat, sogar aus dem eigenen OV in der Wetterau. Und ein paar SOTA-Aktivierern konnte ich bei ihrer Aktivierung helfen.</p><p><img src="'+k+'" alt="Die QSO-Karte von SI-0453 zeigt fast nur Verbindungen nach Norden"></p><p>Auff\xE4llig: Auf 40m wurde ich tagelang fast nur nach Norden geh\xF6rt, von Frankreich \xFCber Deutschland bis Polen. Richtung Osten und S\xFCden kam kaum etwas. Das sieht nach toter Zone auf 40m aus: An diesem Tag kam Cerkno in 50 km mit 59, Innsbruck in rund 280 km nur mit 35 und Berlin in rund 700 km wieder mit 59. In der guten Entfernung liegt s\xFCdlich von S5 eben vor allem die Adria.</p><h2 id="_09-10-si-0514-ucna-vodna-pot-dobrava-abschied-zwischen-hopfengarten" tabindex="-1"><a class="header-anchor" href="#_09-10-si-0514-ucna-vodna-pot-dobrava-abschied-zwischen-hopfengarten" aria-hidden="true">#</a> 09.10.: SI-0514 U\u010Dna vodna pot Dobrava - Abschied zwischen Hopfeng\xE4rten</h2><p><img src="'+f+'" alt="Vertikal vor den Hopfeng\xE4rten bei Radlje ob Dravi"></p><p>Der letzte Tag in S5: grauer Himmel, tief h\xE4ngende Wolken und Hopfeng\xE4rten, so weit das Auge reicht. Der Wasser-Lehrpfad bei Radlje ob Dravi hat einen h\xF6lzernen Aussichtsturm, auf dessen Plattform ich mich eingerichtet habe.</p><p><img src="'+S+'" alt="Betrieb auf der Holzplattform, Mikro in der einen, Handy-Log in der anderen Hand"></p><p>29 QSOs in 53 Minuten aus 9 DXCC-Gebieten, zeitweise mit 48 QSOs pro Stunde. Und endlich ging es auch nach Osten und S\xFCden: HA8WY aus B\xE9k\xE9scsaba kam mit 59 an, dazu zwei Stationen aus Bologna. Zum Abschluss gab es noch ein P2P mit LX1TX aus LU-0044 in Luxemburg.</p><h2 id="fazit" tabindex="-1"><a class="header-anchor" href="#fazit" aria-hidden="true">#</a> Fazit</h2><p>Slowenien kann ich f\xFCr POTA nur empfehlen. Die Natur ist wundersch\xF6n, die Menschen sind freundlich, es gibt viele Parks, und die J\xE4ger rufen flei\xDFig. Plant etwas Zeit f\xFCr die Suche nach den Parkgrenzen ein. Mit pota.app, einem \xDCbersetzer und ein paar slowenischen Vokabeln klappt das aber gut. F\xFCr eine kleine DXpedition mit dem Auto ist S5 ideal.</p><p>F\xFCr alle QSOs gibt es eine eigene QSL-Karte:</p><p><img src="'+_+'" alt="QSL-Karte S5/DA6MAX"></p><p>Danke an alle J\xE4ger f\xFCrs Rufen und f\xFCr eure Geduld. Hvala, Slovenija!</p><p>73 de DA6MAX</p>',37);function y(q,$){const i=o("ExternalLinkIcon");return t(),s("div",null,[v,z,w,e("table",null,[A,e("tbody",null,[e("tr",null,[D,e("td",null,[e("a",P,[O,a(i)])]),T,B]),e("tr",null,[j,e("td",null,[e("a",I,[L,a(i)])]),M,E]),e("tr",null,[H,e("td",null,[e("a",F,[Q,a(i)])]),V,x]),e("tr",null,[W,e("td",null,[e("a",G,[R,a(i)])]),C,X]),e("tr",null,[K,e("td",null,[e("a",N,[U,a(i)])]),Z,J])])]),Y])}var ne=r(b,[["render",y],["__file","2026-10-09-POTA-in-Slowenien-S5-DA6MAX.html.vue"]]);export{ne as default};
